pub fn textAttrSlot(attr_name: []const u8) ?usize {
    if (std.mem.eql(u8, attr_name, "position")) {
        return 0;
    }
    if (std.mem.eql(u8, attr_name, "tex_offset")) {
        return 1;
    }
    if (std.mem.eql(u8, attr_name, "tex_extent")) {
        return 2;
    }
    if (std.mem.eql(u8, attr_name, "size")) {
        return 3;
    }
    if (std.mem.eql(u8, attr_name, "offset")) {
        return 4;
    }
    if (std.mem.eql(u8, attr_name, "transform")) {
        return 5;
    }
    if (std.mem.eql(u8, attr_name, "color0")) {
        return 9;
    }
    if (std.mem.eql(u8, attr_name, "scale")) {
        return 10;
    }
    if (std.mem.eql(u8, attr_name, "char")) {
        return 11;
    }
    return null;
}
pub fn textImageSlot(img_name: []const u8) ?usize {
    if (std.mem.eql(u8, img_name, "tex")) {
        return 0;
    }
    return null;
}
pub fn textSamplerSlot(smp_name: []const u8) ?usize {
    if (std.mem.eql(u8, smp_name, "smp")) {
        return 0;
    }
    return null;
}
pub fn textUniformblockSlot(ub_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        return 0;
    }
    if (std.mem.eql(u8, ub_name, "fs_params")) {
        return 1;
    }
    return null;
}
pub fn textUniformblockSize(ub_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        return @sizeOf(VsParams);
    }
    if (std.mem.eql(u8, ub_name, "fs_params")) {
        return @sizeOf(FsParams);
    }
    return null;
}
pub fn textUniformOffset(ub_name: []const u8, u_name: []const u8) ?usize {
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        if (std.mem.eql(u8, u_name, "zoom")) {
            return 0;
        }
        if (std.mem.eql(u8, u_name, "window_scale")) {
            return 64;
        }
        if (std.mem.eql(u8, u_name, "untransform")) {
            return 128;
        }
    }
    if (std.mem.eql(u8, ub_name, "fs_params")) {
        if (std.mem.eql(u8, u_name, "texture_size")) {
            return 0;
        }
    }
    return null;
}
pub fn textUniformDesc(ub_name: []const u8, u_name: []const u8) ?sg.GlslShaderUniform {
    if (std.mem.eql(u8, ub_name, "vs_params")) {
        if (std.mem.eql(u8, u_name, "zoom")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .MAT4;
            desc.array_count = 0;
            desc.glsl_name = "zoom";
            return desc;
        }
        if (std.mem.eql(u8, u_name, "window_scale")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .MAT4;
            desc.array_count = 0;
            desc.glsl_name = "window_scale";
            return desc;
        }
        if (std.mem.eql(u8, u_name, "untransform")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .MAT4;
            desc.array_count = 0;
            desc.glsl_name = "untransform";
            return desc;
        }
    }
    if (std.mem.eql(u8, ub_name, "fs_params")) {
        if (std.mem.eql(u8, u_name, "texture_size")) {
            var desc: sg.GlslShaderUniform = .{};
            desc.type = .FLOAT2;
            desc.array_count = 0;
            desc.glsl_name = "texture_size";
            return desc;
        }
    }
    return null;
}
